import { useParams, Link } from "react-router-dom";
import { useState, useEffect } from "react";
import Card from "../components/Card";

export default function RoadmapPage() {
  const { name } = useParams();

  const [domain, setDomain] = useState("");
  const [journeyStarted, setJourneyStarted] = useState(false);
  const [learningStarted, setLearningStarted] = useState(false);
  const [currentDay, setCurrentDay] = useState(1);

  const timeline = localStorage.getItem("timeline") || "3 months";

  let totalDays = 90;
  if (timeline.includes("month")) totalDays = parseInt(timeline) * 30;
  else if (timeline.includes("year")) totalDays = parseInt(timeline) * 365;

  useEffect(() => {
    const newDomain = name?.toLowerCase();
    const prevDomain = localStorage.getItem("selectedDomain");

    if (newDomain && prevDomain !== newDomain) {
      localStorage.setItem("selectedDomain", newDomain);

      localStorage.setItem("journeyStarted", "false");
      localStorage.setItem("learningStarted", "false");
      localStorage.setItem("currentDay", "1");
      localStorage.setItem("carryForward", "[]");
      localStorage.removeItem("roadmapPlan");

      setJourneyStarted(false);
      setLearningStarted(false);
      setCurrentDay(1);
    } else {
      setJourneyStarted(localStorage.getItem("journeyStarted") === "true");
      setLearningStarted(localStorage.getItem("learningStarted") === "true");
      setCurrentDay(parseInt(localStorage.getItem("currentDay") || "1"));
    }

    setDomain(newDomain);
  }, [name]);

  // 🔥 MULTI-DOMAIN SUBTOPICS
  const topicMap = {

  "ai-and-ml": [
    ["Python Basics → Datatypes, Variables"],
    ["Loops, Conditions"],
    ["Functions, Lambda"],
    ["NumPy"],
    ["Pandas"],
    ["Visualization"],
    ["Statistics"],
    ["ML Basics"],
    ["Regression"],
    ["Model Evaluation"],
    ["Deep Learning"],
    ["Project"]
  ],

  "web-development": [
    ["HTML → Structure, Forms"],
    ["CSS → Box Model"],
    ["Flexbox, Grid"],
    ["JavaScript Basics"],
    ["DOM"],
    ["ES6"],
    ["React"],
    ["Hooks"],
    ["API"],
    ["Node.js"],
    ["MongoDB"],
    ["Project"]
  ],

  "cloud-and-devops": [
    ["Linux Basics"],
    ["Networking"],
    ["Git"],
    ["Docker"],
    ["CI/CD"],
    ["AWS EC2"],
    ["S3"],
    ["Kubernetes"],
    ["Monitoring"],
    ["Security"],
    ["Deployment"],
    ["Project"]
  ],

  "cybersecurity": [
    ["Networking Basics"],
    ["Cryptography"],
    ["Linux Security"],
    ["Web Security"],
    ["OWASP"],
    ["Ethical Hacking"],
    ["Pen Testing"],
    ["Tools"],
    ["Malware"],
    ["Incident Response"],
    ["Auditing"],
    ["Project"]
  ],

  "data-science": [
    ["Python"],
    ["NumPy"],
    ["Pandas"],
    ["Data Cleaning"],
    ["Visualization"],
    ["Statistics"],
    ["EDA"],
    ["ML Basics"],
    ["Regression"],
    ["Classification"],
    ["Projects"],
    ["Deployment"]
  ],

  "mobile-development": [
    ["Programming Basics"],
    ["Java/Kotlin"],
    ["Android Studio"],
    ["UI Design"],
    ["Layouts"],
    ["API Integration"],
    ["Database"],
    ["Firebase"],
    ["Testing"],
    ["Optimization"],
    ["Deployment"],
    ["Project"]
  ],

  "blockchain": [
    ["Blockchain Basics"],
    ["Cryptography"],
    ["Bitcoin"],
    ["Ethereum"],
    ["Smart Contracts"],
    ["Solidity"],
    ["DApps"],
    ["Web3"],
    ["Security"],
    ["Gas Fees"],
    ["Testing"],
    ["Project"]
  ],

  "ui-ux-design": [
    ["Design Principles"],
    ["Color Theory"],
    ["Typography"],
    ["Wireframing"],
    ["Prototyping"],
    ["Figma"],
    ["User Research"],
    ["UX Flow"],
    ["Testing"],
    ["Accessibility"],
    ["Design System"],
    ["Project"]
  ],

  "big-data": [
    ["Big Data Basics"],
    ["Hadoop"],
    ["MapReduce"],
    ["Spark"],
    ["Kafka"],
    ["Data Pipelines"],
    ["ETL"],
    ["Storage"],
    ["Analytics"],
    ["Scaling"],
    ["Cloud Data"],
    ["Project"]
  ],

  "networking": [
    ["OSI Model"],
    ["TCP/IP"],
    ["IP Addressing"],
    ["Routing"],
    ["Switching"],
    ["DNS"],
    ["HTTP/HTTPS"],
    ["Firewalls"],
    ["Security"],
    ["Troubleshooting"],
    ["Tools"],
    ["Project"]
  ]
};

  const topics = topicMap[domain] || [["Basics"]];

  // 🔥 SMART DISTRIBUTION (3–4 TOPICS PER DAY)
  const generatePlan = () => {
    const plan = [];
    const flatTopics = topics.flat();
    let index = 0;

    for (let day = 1; day <= totalDays; day++) {
      const daily = [];
      const count = 3 + (day % 2); // 3 or 4

      for (let i = 0; i < count; i++) {
        if (index < flatTopics.length) {
          daily.push(flatTopics[index]);
          index++;
        }
      }

      if (daily.length === 0) {
        daily.push("Revision / Practice");
      }

      plan.push(daily);
    }

    return plan;
  };

  useEffect(() => {
    if (!localStorage.getItem("roadmapPlan") && domain) {
      const plan = generatePlan();
      localStorage.setItem("roadmapPlan", JSON.stringify(plan));
    }
  }, [domain]);

  const roadmapPlan = JSON.parse(localStorage.getItem("roadmapPlan") || "[]");

  const getTasksForDay = (day) => {
    const carry = JSON.parse(localStorage.getItem("carryForward") || "[]");

    if (day === currentDay) {
      return [...new Set([...carry, ...(roadmapPlan[day - 1] || [])])];
    }

    return roadmapPlan[day - 1] || [];
  };

  const handleStartJourney = () => {
    localStorage.setItem("journeyStarted", "true");
    setJourneyStarted(true);
  };

  const handleStartToday = () => {
    localStorage.setItem("learningStarted", "true");
    setLearningStarted(true);
  };

  const progress = Math.min((currentDay / totalDays) * 100, 100);

  return (
    <div className="space-y-8">
      <Card title="Learning Roadmap">

        {!journeyStarted && (
          <div className="text-center space-y-4">
            <h3 className="text-xl font-semibold text-slate-900 dark:text-slate-50">
              📚 What you will learn
            </h3>

            <div className="grid gap-3">
              {topics.map((t, i) => (
                <div key={i} className="p-4 rounded-xl border border-slate-300 bg-green-100 dark:border-slate-600 dark:bg-slate-700">
                  Step {i + 1} → {t.join(", ")}
                </div>
              ))}
            </div>

<div className="text-center p-8">
  <h2 className="text-2xl font-bold mb-2">Start Your Learning Journey 🚀</h2>
  <p className="text-gray-400 mb-6">
    Your personalized roadmap will be generated based on your timeline
  </p>

  <button
    onClick={handleStartJourney}
    className="px-6 py-3 bg-gradient-to-r from-green-400 to-blue-500 text-white rounded-xl"
  >
    Start Journey
  </button>
</div>
            
          </div>
        )}

        {journeyStarted && !learningStarted && (
          <div className="text-center">
            <button onClick={handleStartToday} className="px-6 py-3 bg-teal-600 text-white rounded-xl">
              Start From Today 📅
            </button>
          </div>
        )}

        {learningStarted && (
          <>
            <div className="mb-4">
              <div className="w-full bg-slate-200 dark:bg-slate-700 h-3 rounded-full">
                <div
  className="h-3 rounded-full"
  style={{
    width: `${progress}%`,
    background: "linear-gradient(90deg, #22c55e, #4f46e5)",
  }}
/>
              </div>
              <p>{Math.floor(progress)}% completed</p>
            </div>

            <div className="flex items-center justify-between bg-slate-800 p-4 rounded-xl">
  <div>
    <h2 className="text-xl font-bold">Day {currentDay}</h2>
    <p className="text-sm text-gray-400">
      {totalDays - currentDay} days remaining
    </p>
  </div>

  <div className="text-right">
    <p className="text-sm text-gray-400">Timeline</p>
    <p className="font-semibold">{timeline}</p>
  </div>
</div>

            {getTasksForDay(currentDay).map((task, i) => (
              <div className="grid md:grid-cols-2 gap-4 mt-4">
  {getTasksForDay(currentDay).map((task, i) => (
    <div
      key={i}
      className="p-4 rounded-xl bg-slate-800 border border-slate-700 hover:scale-105 transition"
    >
      <div className="flex items-center gap-3">
        <span className="text-green-400 text-lg">✔</span>
        <p className="font-medium">{task}</p>
      </div>
    </div>
  ))}
</div>
            ))}

<div className="flex items-center justify-between mt-6">
  {[...Array(7)].map((_, i) => {
    const day = currentDay - 3 + i;

    return (
      <div key={i} className="flex flex-col items-center">
        <div
          className={`w-4 h-4 rounded-full ${
            day < currentDay
              ? "bg-green-500"
              : day === currentDay
              ? "bg-blue-500 scale-125"
              : "bg-gray-500"
          }`}
        />
        <span className="text-xs mt-1">{day}</span>
      </div>
    );
  })}
</div>

<div className="grid md:grid-cols-3 gap-4 mt-6">
  <div className="p-4 bg-slate-800 rounded-xl">
    <p className="text-gray-400 text-sm">Tasks Today</p>
    <h3 className="text-xl font-bold">
      {getTasksForDay(currentDay).length}
    </h3>
  </div>

  <div className="p-4 bg-slate-800 rounded-xl">
    <p className="text-gray-400 text-sm">Progress</p>
    <h3 className="text-xl font-bold">{Math.floor(progress)}%</h3>
  </div>

  <div className="p-4 bg-slate-800 rounded-xl">
    <p className="text-gray-400 text-sm">Current Domain</p>
    <h3 className="text-xl font-bold capitalize">{domain}</h3>
  </div>
</div>
            <Link to="/tasks">
              <button className="mt-4 px-4 py-2 bg-teal-500 text-white rounded-lg">
                Go to Tasks →
              </button>
            </Link>
          </>
        )}

      </Card>
    </div>
  );
}
